public String render(String template, List<Map<String, Object>> rows) {
    if (StringUtils.isBlank(template)) {
        return "";
    }
    // 取首行作为取值来源：这类模板是单条汇总，不是多行明细
    Map<String, Object> first = CollectionUtils.isEmpty(rows)
            ? Collections.emptyMap() : rows.get(0);
    Matcher m = PLACEHOLDER.matcher(template);     // \$\{(\\w+)\}
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        String field = m.group(1);
        Object value = first.get(field);
        // 找不到的字段按空串处理，不抛错也不留 ${xxx}
        String text = value == null ? "" : value.toString();
        m.appendReplacement(sb, Matcher.quoteReplacement(text));
    }
    m.appendTail(sb);
    return sb.toString();
}

private MimeMessage buildMessage(MailReportJob job, List<MailRecipient> recipients,
                                 String subject, String html) throws Exception {
    MimeMessage message = mailSender.createMimeMessage();
    MimeMessageHelper helper = new MimeMessageHelper(message, true, "UTF-8");
    helper.setSubject(subject);
    helper.setText(html, true);              // true = 按 HTML 解析
    helper.setFrom(fromAddress);
    // 三类收件人分开装配，且只取启用的
    for (MailRecipient r : recipients) {
        if (!Integer.valueOf(1).equals(r.getEnabled())) {
            continue;
        }
        if (TYPE_TO.equals(r.getType())) {
            helper.addTo(r.getEmail());
        } else if (TYPE_CC.equals(r.getType())) {
            helper.addCc(r.getEmail());
        } else if (TYPE_BCC.equals(r.getType())) {
            helper.addBcc(r.getEmail());
        }
    }
    return message;
}
